def diagram(n,title,purpose,audience,els,cs,view):
 d={'id':f'D09-{n:02}','title':title,'purpose':purpose,'audience':audience,'view':view,'model_record_ids':list(dict.fromkeys([e['model_id'] for e in els]+[f for c in cs for f in c['flow_ids']])),'specification':{'elements':els,'connections':cs,'boundary_groups':boundaries,'ordering_constraints':['Actors on left; native desktop then API/domain then service store; external integrations on separate right branch.','Group internal logical components without implying additional deployment.','Threat IDs appear outside component labels.'],'legend':legend,'threat_legend':allthreatlegend if n==4 else {},'annotations':['All controls are specification plans. No observed implementation or verified mitigation.','OD-010–OD-019 are resolved; SC-001–SC-015 are ACTIVE adopted specifications. Required implementation, workload, privacy-review and release evidence remains pending.'],'text_preview':'; '.join(c['source_id']+' → '+c['destination_id']+' ['+c['label']+']' for c in cs)},'omissions':['Exact endpoint methods/paths and runtime topology are not evidenced.','Local protocols beyond stated ports/adapters are not assigned wire protocols.','No universal sensitivity class or risk score is invented.','Operator bootstrap and logs have textual requirements but insufficient component/path detail for a concrete runtime edge.'],'validation_notes':['Model IDs and flow references checked against stage08; not rendered.']}
