def prose(d):
 s=d['specification'];lines=['## '+d['title'],'',f"ID: {d['id']}. Purpose: {d['purpose']}. Audience: {d['audience']}.",'','| Model ID | Element | Kind | Zone | Threats / controls |','| --- | --- | --- | --- | --- |']
 for e in s['elements']:lines.append('| '+' | '.join([e['model_id'],e['label'],e['kind'],e['zone'],', '.join(e.get('threat_ids',[])+e.get('control_ids',[])) or 'None assigned'])+' |')
 lines+=['','| Connection | Source → destination | Data / protocol | Sensitivity | Boundaries |','| --- | --- | --- | --- | --- |']
 for c in s['connections']:lines.append('| '+' | '.join([c['id'],c['source_id']+' → '+c['destination_id'],c['label'],c['data_sensitivity'],', '.join(c['boundary_ids']) or 'None specified'])+' |')
 lines+=['','Text preview: '+s['text_preview'],'','Legend: '+json.dumps(s['legend'],ensure_ascii=False),'','Boundary groups, source annotations, entry authentication/counts and precise ordering constraints are preserved in this diagram’s Model specification.','','Omissions: '+' '.join(d['omissions']),'','Validation: '+' '.join(d['validation_notes'])]
 return '\n'.join(lines)
def write(path,title,model,text):
 (R/'stages'/path).write_text('# '+title+'\n\n## Model\n\n```json\n'+json.dumps(model,indent=2,ensure_ascii=False)+'\n```\n\n'+text+'\n')
